edits.oldText:
export function billingFlag(enabled: boolean) {
  if (!enabled) {
    return { enabled: false, reason: "Off" };
  }
  return { enabled: true };
}

edits.newText:
export function billingFlag(enabled: boolean) {
  if (!enabled) {
    return { enabled: false, reason: "Billing disabled" };
  }
  return { enabled: true };
}
